// Remap Range node: a zero-width input range maps to the
// output minimum instead of dividing by zero.
static inline float flowRemap(float x, float i0, float i1,
                             float o0, float o1) {
  const float d = i1 - i0;
  if (d > -0.000001F && d < 0.000001F) return o0;
  float t = (x - i0) / d;
  if (t < 0.0F) t = 0.0F;
  if (t > 1.0F) t = 1.0F;
  return o0 + (o1 - o0) * t;
}

// Scene "main": graph of "director" (object 13)
class FlowGraphScript_0_13 : public Script {
 public:
  void update(ScriptContext& ctx) override {
    if (ctx.scene != 0) return;
    if (ctx.sceneGeneration != generation) {
      // scene was (re)loaded - back to the initial state
      generation = ctx.sceneGeneration;
      frame = 0;
      started = false;
      timeSec = 0.0F;
      every3 = 1;
    }
    frame++;
    timeSec += g_frameDt;
    if (--every3 <= 0) {
      every3 = everyFrames(1.0F);
      scroller::setSpeed(0, 9, flowRemap(timeSec, 0.0F, 80.0F, -12.0F, -30.0F));
      scroller::setSpeed(0, 12, flowRemap(timeSec, 0.0F, 80.0F, -12.0F, -30.0F));
    }
    if (ctx.engine->pad.getClicked().Cross) {
      scroller::stop(0, 9);
      scroller::stop(0, 12);
    }
    if (ctx.engine->pad.getClicked().Circle) {
      scroller::start(0, 9);
      scroller::start(0, 12);
    }
  }

 private:
  unsigned int generation = 0;
  int frame = 0;
  bool started = false;
  float timeSec = 0.0F;
  int every3 = 1;
};

